                   DELETE FROM amp_global_settings WHERE settingsname='Activity Form - M&E is TabView' AND section='general';
				INSERT INTO amp_global_settings(id, settingsname, settingsvalue, possiblevalues, description, section, value_translatable, internal)
				VALUES ((select max(id) + 1 FROM amp_global_settings), 'Activity Form - M&E is TabView', 'true', 't_Boolean', 'Activity Form - M&E is TabView', 'general', null, FALSE);
